"""Generate the official Core-V ETISS plugin from this repository's submodules."""

import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys

ARCH = "RV32IMACFDXCoreV"
ROOT = Path(__file__).resolve().parents[1]


def generate(m2isar, work):
    # Refuse to reuse a directory: stale generated files must never reach the PR.
    work.mkdir(parents=True, exist_ok=False)
    corev = ROOT / "CoreV_ISA_CoreDSL"
    top_file = corev / "top.core_desc"
    top = top_file.read_text()
    if "XMNN" in top:
        raise ValueError("XMNN remains in Core-V description")
    env = dict(os.environ, PYTHONPATH=str(m2isar))
    subprocess.run([sys.executable, "-m", "m2isar.frontends.coredsl2.parser",
                    str(top_file), "--output", str(work / "gen_model"),
                    "-I", str(corev / "rv_base"),
                    "--infer-types", "--validate"], env=env, check=True)
    subprocess.run([sys.executable, "-m", "m2isar.backends.etiss.writer",
                    str(work / "gen_model/top.m2isarmodel"), "--separate",
                    "--static-scalars", "--coverage", "--fill-mode", "auto"], env=env, check=True)
    output = work / "output" / ARCH
    shutil.copytree(work / "gen_output/top" / ARCH, output)
    for path in output.iterdir():
        if path.suffix in {".h", ".c", ".cpp", ".txt"}:
            text = path.read_text()
            text = re.sub(r"(?m)^([ #*]+)Generated on .*\.$", r"\1Generated by M2-ISA-R; see generation.json.", text)
            path.write_text(text)
    refs = {"top_sha256": hashlib.sha256(top_file.read_bytes()).hexdigest()}
    for name, repo in (("rv_base", corev / "rv_base"),
                       ("rv_xcorev", corev), ("m2isar", m2isar)):
        refs[name] = subprocess.check_output(["git", "-C", str(repo), "rev-parse", "HEAD"], text=True).strip()
    (output / "generation.json").write_text(json.dumps(refs, indent=2, sort_keys=True) + "\n")
    print(output)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--m2isar", type=Path, default=ROOT / "M2-ISA-R")
    parser.add_argument("--work", type=Path, required=True, help="New scratch directory")
    args = parser.parse_args()
    generate(args.m2isar.resolve(), args.work.resolve())
